ON CONFLICT (code) DO UPDATE SET
  name_th = EXCLUDED.name_th,
  name_en = EXCLUDED.name_en;

-- 2. Ensure personnel table exists with proper types and indexes
CREATE TABLE IF NOT EXISTS public.personnel (
    id SERIAL PRIMARY KEY,
    person_id VARCHAR(50) UNIQUE,
    title_th VARCHAR(50),
    name_th VARCHAR(255) NOT NULL,
    name_en VARCHAR(255),
    "position" VARCHAR(100),
    department_code VARCHAR(10) REFERENCES public.departments(code) ON DELETE SET NULL,
    email VARCHAR(255),
    image_url VARCHAR(500),
    first_name VARCHAR(150),
    last_name VARCHAR(150),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE INDEX IF NOT EXISTS personnel_department_code_idx ON public.personnel(department_code);
CREATE INDEX IF NOT EXISTS personnel_name_th_idx ON public.personnel(name_th);

