    ('303', 'นางสาว', 'นางสาวอภิชญา พรมมิ', NULL, '(พนักงานจ้างเหมา)', 'OFS', NULL, '/profile_images/สำนักงานเลขานุการ/นางสาวอภิชญา พรมมิ.jpg', 'อภิชญา', 'พรมมิ', NOW(), NOW()),
    ('304', 'นาย', 'นายโชคชัย ไป๋เขียว', NULL, '(พนักงานจ้างเหมา)', 'OFS', NULL, '/profile_images/สำนักงานเลขานุการ/นายโชคชัย ไป๋เขียว.jpg', 'โชคชัย', 'ไป๋เขียว', NOW(), NOW())
ON CONFLICT (person_id) DO UPDATE SET
    title_th = EXCLUDED.title_th,
    name_th = EXCLUDED.name_th,
    name_en = EXCLUDED.name_en,
    "position" = EXCLUDED."position",
    department_code = EXCLUDED.department_code,
    email = EXCLUDED.email,
    image_url = EXCLUDED.image_url,
    first_name = EXCLUDED.first_name,
    last_name = EXCLUDED.last_name,
    updated_at = NOW();

-- 4. Reset ID sequence
SELECT setval(pg_get_serial_sequence('public.personnel', 'id'), COALESCE(max(id), 1)) FROM public.personnel;

COMMIT;
